'use strict';
const $=s=>document.querySelector(s), esc=v=>String(v??'—').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const num=(n,d=1)=>n==null?'No record':Number(n).toLocaleString('en-IN',{maximumFractionDigits:d});
const money=n=>'₹'+num(n,0), badge=(s,kind='')=>`<span class="badge ${kind}">${esc(s)}</span>`;
const metric=(title,value,note='')=>`<div class="metric"><small>${esc(title)}</small><strong>${value}</strong><em>${esc(note)}</em></div>`;
const api=async(path,body)=>{const r=await fetch('/api/v1'+path,{method:body===undefined?'GET':'POST',headers:{'Content-Type':'application/json'},body:body===undefined?undefined:JSON.stringify(body)});let j;try{j=await r.json()}catch{throw Error('Backend response unavailable')}if(!r.ok)throw Error(typeof j.detail==='string'?j.detail:JSON.stringify(j.detail||j));return j};
const page=location.pathname.split('/').pop().replace('.html','');
const state={mines:[],india:[],selected:localStorage.getItem('mineos-site')||'',map:null,layers:null,allEquipment:[],filterPage:0,run:0};
const nav=[['dashboard','Overview'],['exploration','Exploration'],['maintenance','Fleet & health'],['production','Production'],['decision-center','Decision centre'],['reports','Evidence & results'],['settings','Data & assumptions']];
function shell(){document.body.innerHTML=`<div class="app-shell"><aside class="side"><div class="brand">MineOS <span>AI</span></div><small>Spatial mining intelligence</small><nav>${nav.map(([id,name])=>`<a class="${page===id?'active':''}" href="${id}.html">${name}</a>`).join('')}</nav><div class="side-footer">Mine planning<br>Explore · Plan · Review</div></aside><div class="workspace"><header class="bar"><label>Operational site <select id="site"><option value="">All India sites</option></select></label>${badge('MineOS AI')}<button id="theme-toggle" type="button" aria-pressed="false">Dark mode</button><small id="connection">Connecting…</small></header><main id="content"><div class="loading">Loading MineOS…</div></main></div></div><dialog id="action-dialog"></dialog>`}
function headline(k,t,s){return `<div class="eyebrow">${k}</div><h1>${t}</h1><p class="sub">${s}</p>`}
function error(e){$('#content').insertAdjacentHTML('afterbegin',`<div class="error" role="alert">${esc(e.message)}</div>`)}
function selectedMine(){return state.india.find(m=>m.id===state.selected)}
function makeMap(id,items,click){
 if(state.map){state.map.remove();state.map=null;state.focusMarker=null}
 const el=document.getElementById(id);if(!window.L){el.textContent='Map library unavailable. Use the site selector and tables below.';return}
 const map=L.map(el,{preferCanvas:true}).setView([22,79],5);state.map=map;state.layers=L.layerGroup().addTo(map);
 const streets=L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png',{maxZoom:19,attribution:'© OpenStreetMap contributors'});
 const satellite=L.tileLayer('https://services.arcgisonline.com/ArcGIS/rest/services/World_Imagery/MapServer/tile/{z}/{y}/{x}',{maxZoom:19,attribution:'Tiles © Esri — Source: Esri, Maxar, Earthstar Geographics, and the GIS User Community'});
 const tiles=satellite;tiles.addTo(map);
 L.control.layers({'Satellite':satellite,'Street map':streets},{'Data markers':state.layers}).addTo(map);
 let tileFailed=false;tiles.on('tileerror',()=>{if(!tileFailed){tileFailed=true;el.insertAdjacentHTML('afterend','<p class="muted">Basemap unavailable; data markers and coordinate input remain usable.</p>')}});
 const bounds=[];items.forEach(item=>{if(!Number.isFinite(item.latitude)||!Number.isFinite(item.longitude))return;
  const color=item.status==='inspect'?'#b85140':item.label===0?'#9da58f':item.status==='operational'?'#467c59':'#a56c36';
  L.circleMarker([item.latitude,item.longitude],{radius:item.risk_score!=null?4:5,weight:1,color,fillColor:color,fillOpacity:.75}).bindTooltip(esc(item.name||item.id)).on('click',()=>click?.(item)).addTo(state.layers);bounds.push([item.latitude,item.longitude])});
 if(bounds.length)map.fitBounds(bounds,{padding:[25,25],maxZoom:13,animate:false});const selected=selectedMine();if(selected&&id!=='fleet-map')map.setView([selected.latitude,selected.longitude],11,{animate:false,reset:true});return map;
}
async function overview(){
 const d=await api('/overview');$('#content').innerHTML=headline('Operations / overview','Mine operations at a glance','Track sites in the register, inspect equipment condition and move from exploration to shift planning.')+`<div class="metrics">${metric('Sites in register',d.india_sites,'India occurrence records')}${metric('Equipment records',num(d.fleet.total,0),'Health screening')}${metric('Inspection queue',d.fleet.inspect,'Review these units')}${metric('Satellite patches',num(d.patches,0),'9 spectral bands')}</div><div class="grid"><section class="panel"><div class="row spread"><h2>India site register</h2>${badge('Occurrence data')}</div><div id="overview-map" class="map"></div><p class="footnote">Choose a marker to open its mine plan.</p></section><section class="panel"><h2>Quick actions</h2><p>Start with satellite evidence, then check fleet availability and production outlook.</p><div class="row"><a class="pill-link" href="exploration.html">Explore areas</a><a class="pill-link" href="maintenance.html">Check fleet</a><a class="pill-link" href="production.html">Plan production</a><a class="pill-link" href="decision-center.html">Review actions</a></div><details><summary>Data sources</summary><p>Site register, equipment benchmark, production history and satellite image patches. Current shift reports appear after source logs are added in Data & assumptions.</p></details></section></div>`;
 makeMap('overview-map',state.india,m=>{state.selected=m.id;localStorage.setItem('mineos-site',m.id);location.href='production.html'});
}
async function exploration(){
 document.body.classList.add('exploration-ui');
 const [data,heat]=await Promise.all([api('/exploration/patches'),api('/exploration/heatmap').catch(e=>({features:[],error:e.message}))]);
 $('#content').innerHTML=`<div class="exp-heading"><div>${headline('01 / exploration','Live GIS exploration','Select a point on the map to inspect satellite evidence and review grade or tonnage support.')}</div>${badge('Satellite · spatial screening')}</div><div class="notice">CNN index is a screening response, not a probability or a measured manganese grade. Check the source and local geology before interpreting a point.</div><div class="exp-layout"><aside class="exp-console"><h2>Exploration data</h2><p class="muted">Choose a mine to zoom nearby, or click the map to inspect a point.</p><label class="exp-mine-select">Mine vicinity<select id="exploration-mine"><option value="">Choose a mine…</option>${state.india.map(m=>`<option value="${esc(m.id)}">${esc(m.name)} · ${num(m.latitude,3)}, ${num(m.longitude,3)}</option>`).join('')}</select></label><div class="exp-kpi"><small>Selected coordinates</small><strong id="exp-coords">21.816667, 80.166667</strong></div><div class="exp-kpi"><small>CNN screening index · 0–100</small><strong id="exp-score">—</strong></div><div class="exp-kpi"><small>Gravity anomaly</small><strong id="exp-gravity">No point data</strong></div><div class="exp-kpi"><small>Deposit classification</small><strong id="exp-class">Not supplied</strong></div><div class="exp-kpi"><small>Inspection status</small><strong id="exp-status" class="exp-status">Ready</strong></div><form id="point-form"><div class="form-grid"><label>Latitude<input id="lat" type="number" step="any" min="-90" max="90" value="21.816667" required></label><label>Longitude<input id="lon" type="number" step="any" min="-180" max="180" value="80.166667" required></label><label class="check"><input type="checkbox" id="cloud">Fetch cloud imagery</label><button class="primary" id="predict-point">Inspect point</button></div></form><button type="button" id="nearby-scan">Scan nearby 5 km for 90+ scores</button><div class="exp-nearby"><h3>Nearby high-score points</h3><section id="nearby-result" aria-live="polite"></section></div><p class="status-line" id="point-status" aria-live="polite"></p></aside><div class="exp-stage"><section class="panel exp-map-panel"><div class="row spread"><h2>Satellite map</h2>${badge(data.data.length+' supplied patches')}</div><div id="exploration-map" class="map"></div><p class="legend"><i class="dot"></i>Positive-labelled patch <i class="dot green"></i>Background-labelled patch.</p></section><section class="panel exp-evidence-panel" id="point-result"><h2>Point evidence &amp; subsurface view</h2><p>Select a point to view satellite imagery and the CNN evidence.</p><div class="subsurface-empty"><span>UNDERGROUND MODEL</span><b>No drill geometry supplied</b><small>Ore body, borehole and depth views need surveyed collar coordinates, depth intervals and assay records.</small></div></section></div></div>`;
 const updateCoords=()=>{$('#exp-coords').textContent=Number($('#lat').value).toFixed(6)+', '+Number($('#lon').value).toFixed(6)};
 const map=makeMap('exploration-map',data.data,async r=>{$('#lat').value=r.latitude;$('#lon').value=r.longitude;$('#cloud').checked=false;$('#exploration-mine').value='';if(state.focusMarker){state.map.removeLayer(state.focusMarker);state.focusMarker=null}updateCoords();await runPoint()});
 if(map)await setupScoreHeatmap(map,heat);
 $('#nearby-scan').onclick=scanNearby;
 const mine=selectedMine();if(mine&&map){$('#exploration-mine').value=mine.id;focusExplorationMine(mine,updateCoords)}
 $('#exploration-mine').onchange=()=>{const selected=state.india.find(m=>String(m.id)===$('#exploration-mine').value);if(selected)focusExplorationMine(selected,updateCoords)};
 if(map)map.on('click',e=>{$('#lat').value=e.latlng.lat.toFixed(6);$('#lon').value=e.latlng.lng.toFixed(6);$('#exploration-mine').value='';if(state.focusMarker){state.map.removeLayer(state.focusMarker);state.focusMarker=null}updateCoords();invalidatePoint()});
 ['lat','lon'].forEach(id=>$('#'+id).addEventListener('input',()=>{updateCoords();invalidatePoint()}));
 $('#point-form').onsubmit=e=>{e.preventDefault();runPoint()};document.querySelectorAll('[data-point]').forEach(b=>b.onclick=()=>{const [a,c]=b.dataset.point.split(',');$('#lat').value=a;$('#lon').value=c;updateCoords();runPoint()});
}

function focusExplorationMine(mine,updateCoords){$('#lat').value=mine.latitude;$('#lon').value=mine.longitude;updateCoords();invalidatePoint();if(!state.map)return;if(state.focusMarker)state.map.removeLayer(state.focusMarker);state.focusMarker=L.circleMarker([mine.latitude,mine.longitude],{radius:10,color:'#fff',weight:2,fillColor:'#58a6ff',fillOpacity:.95}).bindPopup('<b>'+esc(mine.name)+'</b><br>'+num(mine.latitude,5)+', '+num(mine.longitude,5)).addTo(state.map);state.map.setView([mine.latitude,mine.longitude],13,{animate:true});}

function ringContainsPoint(ring,x,y){
 let inside=false;
 for(let i=0,j=ring.length-1;i<ring.length;j=i++){
  const [xi,yi]=ring[i],[xj,yj]=ring[j];
  if((yi>y)!==(yj>y)&&x<(xj-xi)*(y-yi)/(yj-yi)+xi)inside=!inside;
 }
 return inside;
}
function insideIndia(lat,lon){
 return (state.indiaPolygons||[]).some(p=>ringContainsPoint(p[0],lon,lat)&&!p.slice(1).some(h=>ringContainsPoint(h,lon,lat)));
}
function indiaHeatLayers(){return [...state.scoreCells.values()].filter(l=>{const c=l.getBounds().getCenter();return insideIndia(c.lat,c.lng)})}
async function setupScoreHeatmap(map,collection){
 try{const r=await fetch('vendor/india-boundary.json');if(!r.ok)throw Error('Boundary unavailable');state.indiaPolygons=await r.json()}
 catch(e){state.indiaPolygons=[];state.indiaBoundaryError=true}
 state.scoreCells=new Map();state.scoreHeat=L.featureGroup().addTo(map);state.heatIndex=0;
 document.getElementById('exploration-map').insertAdjacentHTML('beforebegin',`<div class="row" style="margin:12px 0;flex-wrap:wrap"><label><input type="checkbox" id="score-heat-toggle" checked> High CNN response zones &gt;85</label><button type="button" id="score-heat-focus">Show next high-score patch (India)</button><span id="score-heat-count" class="muted"></span></div><p class="muted">Orange: 85–90 · Red: &gt;90 · Purple: supplied barren label conflicts with CNN. Dashed: in-sample. Bright dots locate scored patches at low zoom; they do not indicate deposit size. Zoom in for the evaluated 1.28 km footprint. Gaps are unscored. Basemap imagery is for context and may differ from the CNN image date. Scores do not confirm manganese.</p>`);
 for(const f of collection.features||[])putScoreCell(f);
 $('#score-heat-toggle').onchange=e=>{if(e.target.checked)state.scoreHeat.addTo(map);else map.removeLayer(state.scoreHeat)};
 $('#score-heat-focus').onclick=()=>{const layers=indiaHeatLayers();if(layers.length){const layer=layers[state.heatIndex++%layers.length];$('#score-heat-toggle').checked=true;state.scoreHeat.addTo(map);map.invalidateSize();map.setView(layer.getBounds().getCenter(),14,{animate:false,reset:true});layer.getLayers()[0]?.openPopup()}};
 map.on('moveend',updateHeatCount);
 updateHeatCount();
 if(collection.error)$('#score-heat-count').textContent='Saved overlay unavailable; inspected scores will still appear.';
 if(state.scoreCells.size&&!selectedMine())requestAnimationFrame(()=>$('#score-heat-focus').click());
}
function updateHeatCount(){const layers=indiaHeatLayers(),count=layers.length,visible=layers.filter(l=>state.map.getBounds().intersects(l.getBounds())).length;$('#score-heat-count').textContent=state.indiaBoundaryError?'India boundary unavailable; navigation disabled.':count?visible+' visible / '+count+' India patches >85':'No scored patches >85 inside India yet. Inspect a point to add one.';$('#score-heat-focus').disabled=!count}

function putScoreCell(f){
 const key=JSON.stringify(f.geometry.coordinates[0].map(p=>p.map(v=>Number(v.toFixed(5)))));
 const old=state.scoreCells.get(key);if(old){state.scoreHeat.removeLayer(old);state.scoreCells.delete(key)}
 const p=f.properties,score=Number(p.score);
 if(Number.isFinite(score)&&score>.85&&score<=1){
  const inSample=['train','validation','calibration'].includes(p.split),color=p.conflict?'#c084fc':score>.90?'#ef3038':'#ffae25';
  const layer=L.geoJSON(f,{style:{color,weight:2,fillColor:color,fillOpacity:.35+.3*(score-.85)/.15,dashArray:inSample?'5 4':null},onEachFeature:(_,l)=>l.bindPopup(`<b>${esc(p.name)}</b><br>CNN index: ${num(score*100,2)}/100<br>Date: ${esc(p.date||'No record')}<br>Source: ${esc(p.source)}<br>Split: ${esc(p.split)}${p.label!=null?'<br>Supplied label: '+(p.label===0?'barren':'positive'):''}${p.conflict?'<br><b>Label conflict / false positive</b>':''}${inSample?'<br><b>In-sample; not independent evidence</b>':''}<br>CNN screening score.`)});
  const popup=layer.getLayers()[0].getPopup().getContent();L.circleMarker(layer.getBounds().getCenter(),{radius:9,color:'#fff',weight:2,fillColor:color,fillOpacity:1,bubblingMouseEvents:false}).bindTooltip(num(score*100,1)+'/100 · scored patch').bindPopup(popup).addTo(layer);
  state.scoreHeat.addLayer(layer);state.scoreCells.set(key,layer);
 }
 updateHeatCount();
}

function invalidatePoint(){state.run++;state.scan=(state.scan||0)+1;$('#point-result').innerHTML='<h2>Point evidence &amp; subsurface view</h2><p>Inspect this point to obtain its CNN score.</p><div class="subsurface-empty"><span>UNDERGROUND MODEL</span><b>No drill geometry supplied</b><small>Ore body and borehole shapes require surveyed collar coordinates, depth intervals and assays.</small></div>';$('#exp-score').textContent='—';$('#exp-gravity').textContent='No point data';$('#exp-class').textContent='Not supplied';$('#exp-status').textContent='Ready';$('#point-status').textContent='';$('#nearby-result').replaceChildren();$('#predict-point').disabled=false;$('#nearby-scan').disabled=false;}
async function runPoint(){
 invalidatePoint();
 const button=$('#predict-point'),status=$('#point-status');button.disabled=true;status.textContent='Reading imagery and running the CNN…';$('#exp-status').textContent='Inspecting imagery…';$('#exp-coords').textContent=Number($('#lat').value).toFixed(6)+', '+Number($('#lon').value).toFixed(6);
 const token=++state.run, target={latitude:Number($('#lat').value),longitude:Number($('#lon').value)};
 try{const q=await api('/exploration/predict',{latitude:Number($('#lat').value),longitude:Number($('#lon').value),cloud:$('#cloud').checked});let r;
  for(let i=0;i<180;i++){r=await api('/jobs/'+q.job_id);if(token!==state.run)return;if(r.status==='complete')break;if(r.status==='failed')throw Error(r.error);status.textContent=r.status==='running'?'Processing imagery…':'Queued…';await new Promise(resolve=>setTimeout(resolve,1500))}
  if(r.status!=='complete')throw Error('Processing is taking longer than expected. Check status and retry.');const d=r.result;
  const gs=d.geographic_support||{};
  if(d.footprint&&state.scoreHeat)putScoreCell({type:'Feature',geometry:d.footprint,properties:{score:d.prospectivity_score,name:d.sample_label_name||'Inspected point',date:d.source.date||d.source.acquisition_date,split:d.sample_split||'cloud inspection',label:d.sample_label,conflict:d.sample_label_conflict,source:d.source.source||d.source.kind}});
  $('#point-result').innerHTML=`<div class="row spread"><h2>Point evidence &amp; subsurface view</h2>${badge(d.sample_split&&d.sample_independent===false?'In-sample · not validation':d.sample_label_conflict?'Model contradicts sample label':'CNN screening','warn')}</div><div class="score">${num(d.prospectivity_score*100)}</div>${d.sample_label_note?`<div class="${d.sample_label_conflict?'error':'notice'}"><b>${esc(d.sample_label===0?'Supplied label: barren':'Supplied label: positive')}</b>${d.sample_label_name?' · '+esc(d.sample_label_name):''}<br>${esc(d.sample_label_note)}</div>`:''}${d.source.fallback_warning?`<div class="notice">${esc(d.source.fallback_warning)}${d.source.distance_km!=null?' Nearest supplied patch: '+num(d.source.distance_km)+' km away.':''}</div>`:''}<p class="muted"><b>${esc(d.score_label||'CNN response index (0–100)')}; not a probability.</b> Global spatial test ROC-AUC ${num(d.test_metrics.roc_auc,3)}. ${esc(d.score_meaning||'Use alongside geological and assay data.')}</p><div class="exp-analysis"><div><h3>Satellite model response</h3><img class="result-img exp-heatmap" src="${d.heatmap}" alt="Grad-CAM overlay on Sentinel imagery"><p class="muted">${esc(d.heatmap_note)}</p></div><div class="subsurface-empty"><span>UNDERGROUND MODEL</span><b>No drill geometry supplied</b><small>Ore body and borehole shapes are not inferred from the CNN score. Add surveyed collars, depth intervals and assays to render a subsurface section.</small></div></div><div class="details"><div><b>Scored imagery location</b>${num(d.location.latitude,5)}, ${num(d.location.longitude,5)}</div><div><b>Valid pixels</b>${num(d.raster.valid_fraction*100)}%</div><div><b>Acquisition</b>${esc(d.source.date||d.source.acquisition_date||'Date unavailable')}</div><div><b>Nearby training support</b>${gs.positive_training_patches??0} positive-labelled, ${gs.background_training_patches??0} background patches within ${gs.radius_km??25} km; nearest positive ${gs.nearest_positive_km==null?'none':num(gs.nearest_positive_km)+' km'}</div><div><b>Training label</b>${esc(gs.background_label_caveat||'Background is not proof of barren ground.')}</div></div><h3>Nearby reported occurrences</h3>${d.nearby_occurrences.map(m=>`<p class="muted">${esc(m.name)} · ${num(m.distance_km)} km<br>Reported grade: ${esc(m.reported_grade)}<br>Source resource: ${esc(m.reported_resource)} (units unverified)</p>`).join('')}`;
  $('#exp-score').textContent=num(d.prospectivity_score*100,2)+'/100';$('#exp-status').textContent='Inspection complete';$('#exp-gravity').textContent=d.gravity_mgal!=null?num(d.gravity_mgal,2)+' mGal':'No point data';$('#exp-class').textContent=d.classification?esc(d.classification):'Not supplied';
  $('#point-result').insertAdjacentHTML('afterbegin','<div id="point-estimation"></div>');
  MineOSEstimation.attach($('#point-estimation'),{...target,prospectivity_score:d.prospectivity_score,note:'CNN imagery location: '+d.location.latitude+', '+d.location.longitude+'. Grade lookup uses the selected coordinates; imagery may be a nearby supplied patch.'});
  status.textContent='Complete. '+(d.source.source||d.source.kind||'Local imagery');
 }catch(e){if(token!==state.run)return;const message=e.message.includes('429')?e.message+' Repeated clicks are cached after a successful fetch. If rate limiting continues, wait a few minutes and retry once.':e.message;status.textContent=message;$('#exp-status').textContent='Unavailable';$('#point-result').innerHTML=`<h2>Prediction unavailable</h2><p class="error">${esc(message)}</p>`}finally{if(token===state.run)button.disabled=false}
}
async function operations(){
 const d=await api('/operational/equipment'+(state.selected?'?mine_id='+encodeURIComponent(state.selected):''));state.allEquipment=d.machines;state.filterPage=0;
 $('#content').innerHTML=headline('02 / operational intelligence','Equipment availability and health','Select a mine to review its equipment, condition and availability.')+`<div class="metrics">${metric('Assigned records',d.summary.total)}${metric('Operational',d.summary.operational,'Health screening')}${metric('Inspection queue',d.summary.inspect,'Prioritize field review')}${metric('Standby candidates',d.summary.available_standby,'Eligible for planner review')}</div><div class="grid"><section class="panel"><h2>Equipment locations</h2><div id="fleet-map" class="map"></div><p class="legend">Green: operational · Red: review condition.</p></section><section class="panel"><h2>Availability by type</h2><div class="table-wrap"><table><thead><tr><th>Type</th><th>Operational / total</th><th>Standby</th></tr></thead><tbody>${Object.entries(d.summary.by_type).map(([k,v])=>`<tr><td>${esc(k)}</td><td>${v.operational} / ${v.total}</td><td>${v.standby}</td></tr>`).join('')}</tbody></table></div></section></div><section class="panel"><div class="row spread"><h2>Equipment register</h2>${badge('Health model')}</div><div class="filters"><input id="equipment-search" placeholder="Search machine ID or type" aria-label="Search machines"><select id="equipment-status" aria-label="Health filter"><option value="">All conditions</option><option>operational</option><option>inspect</option></select><label class="check"><input type="checkbox" id="standby">Eligible standby only</label></div><div class="table-wrap" id="equipment-table"></div><div class="row page-actions"><button id="prev-machines">Previous</button><span id="machine-page"></span><button id="next-machines">Next</button></div><p class="footnote">Review flagged units before dispatch. See Data & assumptions for input coverage.</p></section>`;
 makeMap('fleet-map',d.machines,m=>{$('#equipment-search').value=m.id;renderMachines()});
 ['equipment-search','equipment-status','standby'].forEach(id=>$('#'+id).oninput=()=>{state.filterPage=0;renderMachines()});
 $('#prev-machines').onclick=()=>{state.filterPage=Math.max(0,state.filterPage-1);renderMachines()};$('#next-machines').onclick=()=>{state.filterPage++;renderMachines()};renderMachines();
}
function renderMachines(){let rows=state.allEquipment.filter(m=>(m.id+' '+m.type).toLowerCase().includes($('#equipment-search').value.toLowerCase())&&(!$('#equipment-status').value||m.status===$('#equipment-status').value)&&(!$('#standby').checked||m.eligible));const n=Math.max(1,Math.ceil(rows.length/25));state.filterPage=Math.min(state.filterPage,n-1);$('#machine-page').textContent=`Page ${state.filterPage+1} / ${n} · ${rows.length} records`;$('#next-machines').disabled=state.filterPage>=n-1;$('#prev-machines').disabled=state.filterPage===0;
 $('#equipment-table').innerHTML=`<table><thead><tr><th>ID / type</th><th>Mine</th><th>Condition</th><th>Failure score</th><th>Dispatch</th><th>Observed sensors</th></tr></thead><tbody>${rows.slice(state.filterPage*25,(state.filterPage+1)*25).map(m=>`<tr><td>${esc(m.id)}<br>${esc(m.type)}</td><td>${esc(m.mine_name)}<br><small>${esc(m.mapping_source)} · ${esc(m.mapping_date||'Undated')}</small></td><td>${badge(m.status,m.status==='operational'?'good':'bad')}</td><td>${num(m.risk_score*100)}%<br><small>Model estimate</small></td><td>${m.reserved?'Planned for '+esc(m.planned_destination||'approved action'):m.eligible?'Standby candidate':m.status==='inspect'?'Inspect before dispatch':'Assigned duty'}</td><td><details><summary>Sensor values</summary>${Object.entries(m.sensors).map(([k,v])=>esc(k)+': '+num(v)).join('<br>')}<br>Benchmark recorded failure: ${m.recorded_benchmark_failure===1?'Yes':'No'}<br>Sensor observation time unavailable; benchmark, not live telemetry.<br>Mapping: ${esc(m.mapping_source)}</details></td></tr>`).join('')||'<tr><td colspan="6">No matching machines</td></tr>'}</tbody></table>`;
}
function scenarioForm(){return `<form id="scenario-form"><div class="form-grid"><label>Data mode<select name="mode"><option value="replay">Historical replay</option><option value="forecast">Forecast / scenario</option></select></label><label>Dataset block<select name="replay_block"><option>Block-A</option><option>Block-B</option><option>Block-C</option></select></label><label>Replay date<input name="replay_date" type="date"></label><label>Period<select name="period"><option value="daily">Daily</option><option value="shift">One shift</option><option value="weekly">Next 7 days</option><option value="monthly">30-day scenario</option></select></label><label>Shift<select name="shift"><option>Shift-1</option><option>Shift-2</option><option>Shift-3</option></select></label><label>Blast delay h/shift<input name="blast_delay_hours" type="number" step=".25" min="0" max="8" placeholder="Mine simulation"></label><label>Rain mm/day (blank = feed)<input name="rainfall_mm" type="number" step=".1" min="0" max="1000" placeholder="Use weather / scenario proxy"></label><label>Target MT/shift (optional)<input name="target_per_shift_mt" type="number" min="0" max="100000" placeholder="Historical plan template"></label><label>Price ₹/tonne<input name="price_per_tonne" type="number" min="0" value="10000"></label><label>Variable cost ₹/tonne<input name="variable_cost_per_tonne" type="number" min="0" value="4000"></label><label class="check"><input name="live_weather" type="checkbox" checked>Live weather (15-minute cache)</label></div><details><summary>Recovery costs & capacity assumptions</summary><div class="form-grid">${[['stockpile_mt','Stockpile MT',200],['stockpile_handling_per_tonne','Handling ₹/tonne',250],['processing_headroom_tph','Spare plant capacity t/h',20],['max_transfer_km','Max transfer km',200],['transport_speed_kph','Transport km/h',25],['mobilization_inr','Mobilisation ₹',8000],['transport_inr_per_km','Transport ₹/km',120],['extra_shift_hours','Extra hours/shift (max 2)',1],['overtime_cost_per_hour','Overtime ₹/h',3000]].map(([k,l,v])=>`<label>${l}<input name="${k}" type="number" min="${k==='transport_speed_kph'?1:0}" ${k==='extra_shift_hours'?'max="2"':''} value="${v}" step="any"></label>`).join('')}</div></details><div class="row"><button class="primary" id="run-scenario">${page==='decision-center'?'Compare recovery actions':'Calculate forecast'}</button><span class="muted">Edit price and cost inputs for each scenario.</span></div></form>`}
function readScenario(){const form=new FormData($('#scenario-form')),saved=JSON.parse(localStorage.getItem('mineos-scenario-'+state.selected)||'{}'),d={};for(const k of ['fleet_available_pct_override','fleet_risk_pct_override','equipment_downtime_hours'])if(saved[k]!=null)d[k]=saved[k];for(const [k,v] of form){if(['live_weather','simulate_events'].includes(k)){d[k]=true;continue}if(v==='')continue;d[k]=['period','shift','mode','replay_block','replay_date'].includes(k)?v:Number(v)}d.live_weather=!!d.live_weather;d.simulate_events=false;localStorage.setItem('mineos-scenario-'+state.selected,JSON.stringify(d));return d}
async function productionPage(){
 const decision=page==='decision-center';
 const content=headline(decision?'04 / decisions':'03 / production',decision?'Act on the ranked recovery plan.':'Know the gap before the next shift.','Forecast uses selected site inputs, available weather and equipment history.')+
 (decision?'<div id="decision-actions"></div><div id="decision-summary"></div><details id="decision-advanced"><summary>Advanced settings</summary><p class="muted">Optional scenario controls. Uses this mine’s saved Production settings; defaults apply if none were saved.</p><section class="panel">'+scenarioForm()+'<p class="status-line" id="forecast-status" aria-live="polite"></p></section></details>':'<section class="panel">'+scenarioForm()+'<p class="status-line" id="forecast-status" aria-live="polite"></p></section>')+
 '<div id="forecast-output"></div><section class="panel"><h2>Mine selection</h2><div id="production-map" class="map"></div></section>';
 $('#content').innerHTML=content;
 makeMap('production-map',state.india,m=>{state.selected=m.id;$('#site').value=m.id;localStorage.setItem('mineos-site',m.id);render()});
 const saved=JSON.parse(localStorage.getItem('mineos-scenario-'+state.selected)||'null');
 if(saved&&!saved.mode){saved.mode='replay';saved.simulate_events=false;}
 if(saved)for(const [k,v] of Object.entries(saved)){const el=$('#scenario-form').elements.namedItem(k);if(el){if(el.type==='checkbox')el.checked=v;else el.value=v}}
 const evidence=await api('/site-inputs/'+state.selected).catch(()=>({inputs:{}}));for(const [k,v] of Object.entries(evidence.inputs)){const el=$('#scenario-form').elements.namedItem(k);if(el&&k!=='block')el.value=v;}
 if(evidence.inputs.block)$('#scenario-form').elements.replay_block.value=evidence.inputs.block;
 const replayInfo=await api('/replay-dates');const dateInput=$('#scenario-form').elements.replay_date;dateInput.min=replayInfo.dates[0];dateInput.max=replayInfo.dates.at(-1);if(!dateInput.value)dateInput.value=replayInfo.dates[0];
 $('#scenario-form').insertAdjacentHTML('beforeend','<div class="row"><button type="button" id="rain-scenario">Heavy rainfall · 75 mm/day</button><button type="button" id="blast-scenario">Blasting delay · 3 h/shift</button><button type="button" id="reset-scenario">Use current conditions</button></div><p class="muted">Buttons apply hypothetical conditions. Weather refreshes automatically. Scenario controls apply to the selected site.</p>');
 $('#rain-scenario').onclick=()=>{$('#scenario-form').elements.mode.value='forecast';$('#scenario-form').elements.rainfall_mm.value=75;runForecast()};
 $('#blast-scenario').onclick=()=>{$('#scenario-form').elements.mode.value='forecast';$('#scenario-form').elements.blast_delay_hours.value=3;runForecast()};
 $('#reset-scenario').onclick=()=>{$('#scenario-form').elements.mode.value='forecast';for(const k of ['rainfall_mm','blast_delay_hours'])$('#scenario-form').elements[k].value='';$('#scenario-form').elements.live_weather.checked=true;runForecast()};
 $('#scenario-form').insertAdjacentHTML('beforeend','<button type="button" id="replay-next">Replay next recorded day</button>');$('#replay-next').onclick=()=>{const e=$('#scenario-form').elements;const i=replayInfo.dates.indexOf(e.replay_date.value);e.replay_date.value=replayInfo.dates[Math.min(i+1,replayInfo.dates.length-1)];e.mode.value='replay';runForecast()};
 $('#scenario-form').onsubmit=e=>{e.preventDefault();runForecast()};await runForecast();
 state.refresh=setInterval(()=>{if(!document.hidden&&!$('#action-dialog').open&&!$('#run-scenario').disabled)runForecast()},60000);
}
function chart(rows,history=[]){
 const data=[...history.slice(-9),...rows],n=data.length,x=i=>55+i*810/Math.max(1,n-1),max=Math.max(1,...data.flatMap(r=>[r.target_mt||0,r.predicted_mt||0,r.actual_mt||0])),y=v=>195-v/max*150;
 const lines=[['target_mt','#7b9572','Target'],['predicted_mt','#cf873d','Predicted'],['actual_mt','#329dcc','Recorded actual']];
 return `<svg viewBox="0 0 900 255" class="chart" role="img" aria-label="Historical actual, predicted and target production in metric tonnes">${[0,.5,1].map(f=>`<line x1="50" y1="${y(f*max)}" x2="875" y2="${y(f*max)}" stroke="#ddd"/><text x="0" y="${y(f*max)}" font-size="10">${num(f*max,0)}</text>`).join('')}${lines.map(([k,color])=>{let segments=[],segment=[];data.forEach((r,i)=>{if(r[k]==null){if(segment.length)segments.push(segment);segment=[]}else segment.push([x(i),y(r[k]),r,i])});if(segment.length)segments.push(segment);return segments.map(seg=>`<polyline fill="none" stroke="${color}" stroke-width="2.5" points="${seg.map(p=>p.slice(0,2).join(',')).join(' ')}"/>`+seg.map(([cx,cy,r])=>`<circle cx="${cx}" cy="${cy}" r="3" fill="${color}"><title>${esc(r.date+' '+r.shift)}: ${num(r[k])} MT</title></circle>`).join('')).join('')}).join('')}${data.map((r,i)=>i===0||i===n-1||i===history.slice(-9).length?`<text x="${x(i)}" y="225" text-anchor="middle" font-size="10">${esc(r.date)} ${esc(r.shift)}</text>`:'').join('')}<text x="55" y="250" font-size="11">MT · Recorded actuals only; model estimates are not measurements.</text></svg>`;
}
async function runForecast(){
 const requestId=state.forecast=(state.forecast||0)+1; const button=$('#run-scenario'),status=$('#forecast-status');button.disabled=true;status.textContent='Calculating from model and fleet…';const opts={...JSON.parse(localStorage.getItem('mineos-scenario-'+state.selected)||'{}'),...readScenario()},decision=page==='decision-center';
 try{if(!state.selected){
   if(opts.mode==='replay'){$('#forecast-output').innerHTML='<p class="notice">Choose a site context above to view the selected dataset block. Historical block data is not summed across unrelated mines.</p>';status.textContent='Historical replay selected.';return;}
   if(decision){$('#forecast-output').innerHTML='<div class="notice">Select one mine to compare feasible recovery actions. Recommendations need a specific destination and capacity constraints.</div>';status.textContent='Select a mine above or on the map.';return}
   const items=[];for(const m of state.india){if(requestId!==state.forecast)return;status.textContent=`Calculating ${items.length+1}/${state.india.length} demo sites…`;items.push(await api('/production/'+m.id,{...opts,live_weather:false}))}
   if(requestId!==state.forecast)return; const sum=k=>items.reduce((s,r)=>s+r[k],0);$('#forecast-output').innerHTML=`<div class="metrics">${metric('Target',num(sum('target_mt'))+' MT')}${metric('Predicted',num(sum('predicted_mt'))+' MT')}${metric('Shortfall',num(sum('shortfall_mt'))+' MT')}${metric('Gross revenue at risk',money(sum('gross_revenue_at_risk_inr')),'Scenario valuation, not accounting loss')}</div><section class="panel"><h2>All-site scenarios</h2><div class="notice">Illustrative total across listed sites using selected production history. Live weather is fetched per selected site.</div><div class="table-wrap"><table><thead><tr><th>Mine</th><th>Target MT</th><th>Forecast MT</th><th>Shortfall MT</th></tr></thead><tbody>${items.map(d=>`<tr><td>${esc(d.mine.name)}</td><td>${num(d.target_mt)}</td><td>${num(d.predicted_mt)}</td><td>${num(d.shortfall_mt)}</td></tr>`).join('')}</tbody></table></div></section>`;status.textContent='All-site scenarios calculated.';return;
  }
  const response=await api((decision?'/decisions/':'/production/')+state.selected,opts),d=decision?response.baseline:response; if(requestId!==state.forecast)return;
  if(decision){$('#decision-actions').innerHTML=actionCards(response);document.querySelectorAll('#decision-actions [data-action]').forEach(b=>b.onclick=()=>actionDialog(b.dataset.action,b.dataset.state));$('#decision-summary').innerHTML=`<div class="metrics">${metric('Planned target',num(d.target_mt)+' MT')}${metric('Expected shortfall',num(d.shortfall_mt)+' MT',num(d.shortfall_pct)+'%')}${metric('Revenue at risk',money(d.gross_revenue_at_risk_inr),'Scenario estimate')}</div>`;}
  $('#forecast-output').innerHTML=`<div class="metrics">${metric('Planned target',num(d.target_mt)+' MT')}${metric('Predicted output',num(d.predicted_mt)+' MT',d.period+' conditional scenario')}${metric('Expected shortfall',num(d.shortfall_mt)+' MT',num(d.shortfall_pct)+'% of target')}${metric('Gross revenue at risk',money(d.gross_revenue_at_risk_inr),'Not profit loss; scenario price')}</div><div class="grid"><section class="panel"><h2>${esc(d.mine.name)} · production outlook</h2>${chart(d.rows,d.historical_rows||[])}<p class="legend">Blue: supplied/operator-recorded actual · Sage: target · Copper: model estimate · Range ${num(d.lower_mt)}–${num(d.upper_mt)} MT (scenario error band)</p><details><summary>Inspect shift rows and weather inputs</summary><div class="table-wrap"><table><thead><tr><th>Date / shift</th><th>Target</th><th>Predicted</th><th>Rain</th><th>Weather source</th></tr></thead><tbody>${d.rows.map(r=>`<tr><td>${r.date} ${r.shift}</td><td>${num(r.target_mt)}</td><td>${num(r.predicted_mt)}</td><td>${num(r.rainfall_mm)} mm</td><td>${esc(r.weather_source)}</td></tr>`).join('')}</tbody></table></div></details></section><section class="panel"><h2>Inputs & limitations</h2><div class="details"><div><b>Fleet available</b>${num(d.fleet_availability_pct)}%</div><div><b>Weather feed</b>${esc(d.weather.status)}</div><div><b>${d.mode==='replay'?'Recorded replay actual':'Operator-recorded actual'}</b>${num(d.current_production_mt)} MT</div><div><b>Last supplied history</b>${esc(d.historical_as_of)} · ${num(d.last_historical_production_mt)} MT</div></div><p class="notice">${d.mode==='replay'?'Recorded dataset actuals + model reconstruction.':'Model forecast. Actuals, when present, are operator-entered.'} Money values depend on operator inputs or scenario rates.</p><p class="muted">${esc(d.assumptions.production_mapping)}</p><p class="muted">${esc(d.assumptions.interval)}</p><p class="muted">Blasting delay assumption: ${num(d.assumptions.blast_delay_hours)} h/shift. ${esc(d.assumptions.blast_source)}; recorded shift logs take precedence when no override is set.</p><p class="muted">${d.weather.retrieved_at?'Weather fetched '+esc(d.weather.retrieved_at):'Weather source:'}</p><a href="https://open-meteo.com/" target="_blank" rel="noreferrer">Weather: Open-Meteo (CC BY 4.0)</a></section></div>${approvedPlans(d)}`;
  document.querySelectorAll('[data-action]').forEach(b=>b.onclick=()=>actionDialog(b.dataset.action,b.dataset.state));
  status.textContent='Updated '+new Date(d.updated_at).toLocaleTimeString()+'. '+(d.weather.error?'Weather unavailable: '+d.weather.error:'');
 }catch(e){if(requestId!==state.forecast)return;status.textContent=e.message;$('#forecast-output').innerHTML=`<div class="error">${esc(e.message)}</div>`}finally{if(requestId===state.forecast){button.disabled=false;polishSections()}}
}
function actionCards(r){return `<section class="panel"><h2>Ranked recovery alternatives</h2><div class="notice">${esc(r.note)}</div>${r.actions.map(a=>`<article class="action"><div class="row spread"><div class="row"><span class="action-number">${a.rank}</span><h3>${esc(a.title)}</h3></div>${badge(a.state,a.net_benefit_inr<0?'bad':'')}</div><p>${esc(a.reason)}</p><p class="muted">Ranked from predicted supply, equipment availability and recovery cost.</p><div class="action-values"><div><b>${num(a.extra_supply_mt)} MT</b><span>Extra supply (${num(a.extra_mined_mt)} newly mined)</span></div><div><b>${money(a.action_cost_inr)}</b><span>Action cost</span></div><div><b>${money(a.net_benefit_inr)}</b><span>After variable + action cost</span></div><div><b>${num(a.remaining_shortfall_mt)} MT</b><span>Remaining deficit</span></div></div><details><summary>Calculation and constraints</summary><p class="muted">Gross value ${money(a.gross_value_inr)} − variable cost ${money(a.variable_cost_inr)} − action cost ${money(a.action_cost_inr)} = ${money(a.net_benefit_inr)}. These are alternatives; do not sum their recovery.</p><p class="muted">${esc(JSON.stringify(a.constraints))}</p>${a.distance_km!=null?`<p class="muted">From ${esc(a.source_mine)} · ${num(a.distance_km)} km · transfer/setup ${num(a.travel_hours)} h.</p>`:''}</details><div class="row">${a.state==='pending'||a.state==='acknowledged'?`${a.state==='pending'?`<button data-action="${a.id}" data-state="acknowledged">Acknowledge</button>`:''}<button class="primary" data-action="${a.id}" data-state="accepted">Approve planned recovery</button><button data-action="${a.id}" data-state="rejected">Reject</button>`:a.state==='accepted'?`<button data-action="${a.id}" data-state="completed">Record actual outcome</button>`:''}</div></article>`).join('')||'<p>No feasible positive-production recovery action for these inputs.</p>'}</section>`}
function actionDialog(id,stateTo){const dialog=$('#action-dialog');dialog.innerHTML=`<form id="action-form"><h2>${stateTo==='completed'?'Record actual outcome':stateTo==='accepted'?'Approve planned recovery':stateTo==='acknowledged'?'Acknowledge recommendation':'Reject / revoke action'}</h2><p class="muted">Approval updates this mine’s planned forecast across Production and Decisions. Physical dispatch and actual output still need field confirmation.</p><label>Operator name<input name="actor" required minlength="2"></label><label>Reason / field evidence<textarea name="reason" required minlength="3"></textarea></label>${stateTo==='completed'?'<label>Actual recovered MT<input type="number" name="actual_recovered_mt" min="0" step="any" required></label><label>Actual action cost ₹<input type="number" name="actual_cost_inr" min="0" step="any" required></label>':''}<p id="action-error" class="muted"></p><div class="row"><button class="primary">Save</button><button type="button" id="cancel-action">Cancel</button></div></form>`;dialog.showModal();$('#cancel-action').onclick=()=>dialog.close();$('#action-form').onsubmit=async e=>{e.preventDefault();const body=Object.fromEntries(new FormData(e.target));body.state=stateTo;for(const k of ['actual_recovered_mt','actual_cost_inr'])if(k in body)body[k]=Number(body[k]);try{await api('/actions/'+id,body);localStorage.setItem('mineos-action-update',Date.now());dialog.close();if(page==='reports')reports();else if(page==='decision-center'){await runForecast();await recoveryPanel()}else runForecast()}catch(err){$('#action-error').textContent=err.message}}}
async function reports(){const [e,r]=await Promise.all([api('/evidence'),api('/records')]);const active=e.active_multimodal_model||{},national=e.national_multimodal_validation||{},c=national.cnn_oof||active.evaluation||{},h=e.tabular.health||{},p=e.tabular.production||{};const nationalReady=!!national.cnn_oof,scope=nationalReady?(national.eligible_for_deployment?'Regional validation passed':'Candidate not deployed'):'Legacy diagnostic; not independent';
 $('#content').innerHTML=headline('05 / evidence','Measured performance. Visible limits.','These results are from supplied datasets and held-out splits. They are not field validation or guaranteed operational savings.')+`<div class="metrics">${metric(nationalReady?'National candidate ROC-AUC':'Active model diagnostic ROC-AUC',num(c.roc_auc,3),scope)}${metric('Occurrence/background PR-AUC',num(c.pr_auc,3),nationalReady?'Whole regions held out':'Not independent field evidence')}${metric('Machine failure recall',num((h.recall||0)*100)+'%','Sensor-only synthetic benchmark')}${metric('Production MAE',num(p.mae_mt)+' MT','Conditional shift model')}</div><div class="grid"><section class="panel evidence"><h2>Validation register</h2><p>Active model: <b>${esc(active.version||'Unknown')}</b>. ${esc(scope)}.</p><table><thead><tr><th>Model</th><th>Evidence</th><th>Constraint</th></tr></thead><tbody><tr><td>Multimodal CNN</td><td>${c.n??'—'} patches · ${national.folds?.length??'—'} held-out regions<br>Balanced accuracy ${num(c.balanced_accuracy,3)}</td><td>${esc(national.label_scope||active.limitations||'Independent validation not established')}</td></tr><tr><td>Equipment</td><td>${h.test_rows} test rows<br>PR-AUC ${num(h.pr_auc,3)}</td><td>No RUL or forecast lead-time validation</td></tr><tr><td>Production</td><td>Model MAE ${num(p.mae_mt)} vs rolling baseline ${num(p.rolling7_mae_mt)} MT</td><td>Realized-weather conditions; mine transfer unvalidated</td></tr><tr><td>Grade</td><td>MAE ${num(e.tabular.grade?.mae_pct)} percentage points</td><td>Unverified source labels; analogue estimate</td></tr><tr><td>Resource</td><td>Unavailable</td><td>Units and volume labels need verification</td></tr></tbody></table><details><summary>Full model metadata</summary><pre>${esc(JSON.stringify(e,null,2))}</pre></details></section><section class="panel"><h2>Observed action outcomes</h2>${metric('Completed actions',r.summary.completed)}${metric('Recorded recovered supply',num(r.summary.actual_recovered_mt)+' MT')}${metric('Recorded action costs',money(r.summary.actual_cost_inr))}<p class="muted">Operator-entered outcomes. Without a control/counterfactual, recovery cannot be attributed causally to the recommendation.</p></section></div><section class="panel"><h2>Decision audit trail</h2><div class="log">${r.data.map(a=>`<article class="log-entry"><div class="row spread"><b>${esc(a.payload.title)}</b>${badge(a.state)}</div><p class="muted">${esc(a.actor||'Awaiting operator')} · ${esc(a.created_at)}<br>${esc(a.reason||'No decision recorded')}</p><p class="muted">Expected recovery ${num(a.payload.extra_supply_mt)} MT · Operator-recorded actual ${num(a.actual_recovered_mt)} MT${a.actual_recovered_mt!=null?' · Difference '+num(a.actual_recovered_mt-a.payload.extra_supply_mt)+' MT':''}</p>${a.state==='accepted'?`<button data-action="${a.id}" data-state="completed">Record outcome</button>`:''}</article>`).join('')||'<p>No decisions yet. Compare actions in the Decision centre.</p>'}</div></section>`;
 document.querySelectorAll('[data-action]').forEach(b=>b.onclick=()=>actionDialog(b.dataset.action,b.dataset.state));
}
async function settings(){const e=await api('/evidence');$('#content').innerHTML=headline('Data / assumptions','Inputs behind the dashboard','Review data sources or add mine, shift, equipment and assay records.')+`<details class="panel"><summary>Data sources and model notes</summary><table><thead><tr><th>Layer</th><th>Source</th><th>Status</th></tr></thead><tbody><tr><td>Imagery</td><td>Supplied 9-band TIFFs + public Sentinel-2 L2A</td><td>${e.dataset.accepted} accepted / ${e.dataset.total_files} files. Cloud imagery on demand.</td></tr><tr><td>Occurrences</td><td>User master CSV</td><td>Reported labels; mine operation and resource units unverified.</td></tr><tr><td>Equipment</td><td>AI4I sensor benchmark</td><td>Equipment readings and mapped locations are separate source fields.</td></tr><tr><td>Production</td><td>Supplied three-block history</td><td>Historical blocks; select a recorded block mapping and add shift logs for actual output.</td></tr><tr><td>Weather</td><td>Open-Meteo public forecast</td><td>Retrieved per selected site; timestamp and fallback shown.</td></tr><tr><td>Costs / blasting</td><td>Editable scenario form</td><td>Rates and delay inputs are editable; add source logs when available.</td></tr></tbody></table></details><section class="panel"><h2>Register a field assay</h2><p class="muted">Results are saved for validation. They do not automatically retrain or replace the model.</p><form id="assay-form"><div class="form-grid"><label>Occurrence<select name="site_id">${state.india.map(m=>`<option value="${m.id}">${esc(m.name)}</option>`).join('')}</select></label><label>Measured Mn %<input name="assay_pct" type="number" min="0" max="100" step="any" required></label><label>Source / sample notes<input name="notes" minlength="5" required></label><button class="primary">Save assay for review</button></div><p id="assay-status" aria-live="polite"></p></form></section>`;$('#assay-form').onsubmit=async ev=>{ev.preventDefault();const d=Object.fromEntries(new FormData(ev.target));d.assay_pct=Number(d.assay_pct);try{const r=await api('/field-results',d);$('#assay-status').textContent='Record '+r.id+' saved. Model unchanged until reviewed.'}catch(err){$('#assay-status').textContent=err.message}}}
async function render(){clearInterval(state.refresh);clearInterval(state.replayTimer);state.replayTimer=null;state.forecast=(state.forecast||0)+1;state.run++;state.scan=(state.scan||0)+1;if(state.map){state.map.remove();state.map=null}$('#content').innerHTML='<div class="loading">Loading data from backend…</div>';try{if(page==='exploration'){await exploration();await explorationLayers()}else if(page==='maintenance'){await operations();await sensorPanel()}else if(['production','decision-center'].includes(page))await productionPage();else if(page==='reports')await reports();else if(page==='settings'){await settings();await evidenceForms();}else {await overview();await executiveGrid()}if(page==='production'){await comparisonPanel();await replayPanel()}if(page==='decision-center')await recoveryPanel();polishSections()}catch(e){$('#content').innerHTML='';error(e)}}
async function boot(){shell();const themeKey=page==="exploration"?"mineos-exploration-theme":"mineos-theme",themeChoice=localStorage.getItem(themeKey),savedTheme=page==="exploration"?themeChoice!=="light":themeChoice==="dark";document.body.classList.toggle("dark",savedTheme);$("#theme-toggle").textContent=savedTheme?"Light mode":"Dark mode";$("#theme-toggle").setAttribute("aria-pressed",String(savedTheme));$("#theme-toggle").onclick=()=>{const dark=document.body.classList.toggle("dark");localStorage.setItem(themeKey,dark?"dark":"light");$("#theme-toggle").textContent=dark?"Light mode":"Dark mode";$("#theme-toggle").setAttribute("aria-pressed",String(dark))};try{const d=await api('/mines');state.mines=d.data;state.india=d.data.filter(m=>m.country==='India');if(!state.india.some(m=>m.id===state.selected))state.selected=state.india[0]?.id||'';$('#site').innerHTML='<option value="">All India sites</option>'+state.india.map(m=>`<option value="${m.id}">${esc(m.name)}</option>`).join('');$('#site').value=state.selected;$('#site').onchange=()=>{state.selected=$('#site').value;localStorage.setItem('mineos-site',state.selected);render()};$('#connection').textContent='Backend connected · source labels active';await render()}catch(e){$('#connection').textContent='Backend unavailable';$('#content').innerHTML='<div class="error">'+esc(e.message)+'<br>Start the MineOS server and refresh. No mock fallback is shown.</div>'}}
boot();

async function scanNearby(){
 const button=$('#nearby-scan'),out=$('#nearby-result'),lat=Number($('#lat').value),lon=Number($('#lon').value);
 if(!$('#point-form').reportValidity())return;
 const scanToken=state.scan=(state.scan||0)+1;
 button.disabled=true;out.textContent='Scanning a 5 km grid using cloud imagery. This may take several minutes…';
 if(state.nearbyLayer)state.map.removeLayer(state.nearbyLayer);
 state.nearbyLayer=L.featureGroup().addTo(state.map);
 const circle=L.circle([lat,lon],{radius:5000,color:'#38bdf8',weight:2,fillOpacity:.03}).addTo(state.nearbyLayer);
 state.map.fitBounds(circle.getBounds(),{animate:false});
 try{
  const q=await api('/exploration/nearby',{latitude:lat,longitude:lon,cloud:true});let job;
  for(let i=0;i<240;i++){
   job=await api('/jobs/'+q.job_id);if(scanToken!==state.scan||!out.isConnected)return;
   if(job.status==='complete')break;
   if(job.status==='failed')throw Error(job.error);
   await new Promise(resolve=>setTimeout(resolve,1500));
  }
  if(job.status!=='complete')throw Error('Scan is still running. No conclusion is available yet.');
  const d=job.result,hits=d.features.filter(f=>f.properties.high_score).sort((a,b)=>b.properties.score-a.properties.score||a.properties.distance_km-b.properties.distance_km);
  for(const f of d.features){const p=f.properties;L.geoJSON(f,{style:{color:p.high_score?'#ef3038':'#879589',weight:p.high_score?3:1,fillOpacity:p.high_score?.5:.06}}).bindPopup('CNN index: '+num(p.score*100,2)+'/100<br>Distance: '+num(p.distance_km,2)+' km<br>Image: '+esc(p.date)+'<br>CNN score for field follow-up.').addTo(state.nearbyLayer)}
  for(const p of d.missing)L.circleMarker([p.latitude,p.longitude],{radius:5,color:'#aaa',dashArray:'3 3'}).bindPopup('Unscored: insufficient clear imagery').addTo(state.nearbyLayer);
  out.innerHTML='<p class="notice">'+esc(d.message)+'</p><p>'+d.scored+'/'+d.total+' grid patches scored · '+d.missing.length+' unavailable<br>Image: '+esc(d.source.acquisition_date)+'</p>'+(hits.length?hits.map((f,i)=>'<article class="nearby-estimate"><button type="button" data-nearby="'+i+'"><b>Priority '+(i+1)+'</b> · '+num(f.properties.score*100,2)+'/100 · '+num(f.properties.distance_km,2)+' km</button><div data-estimate-nearby="'+i+'"></div></article>').join(''):'<p class="muted">No 90+ locations in this scan.</p>');
  out.querySelectorAll('[data-estimate-nearby]').forEach(el=>{const p=hits[Number(el.dataset.estimateNearby)].properties;MineOSEstimation.attach(el,{latitude:p.latitude,longitude:p.longitude,prospectivity_score:p.score})});
  out.querySelectorAll('[data-nearby]').forEach(b=>b.onclick=()=>{const p=hits[Number(b.dataset.nearby)].properties;state.map.setView([p.latitude,p.longitude],14,{animate:false,reset:true})});
 }catch(e){if(scanToken!==state.scan||!out.isConnected)return;out.textContent='Scan incomplete: '+e.message+' No conclusion about manganese absence or extractability can be made.'}
 finally{if(scanToken===state.scan)button.disabled=false}
}

function approvedPlans(d){return `<section class="panel"><h2>Connected mine conditions</h2><p>Mine: ${esc(d.mine.name)} · <a href="maintenance.html">View assigned fleet</a> · <a href="production.html">Production</a> · <a href="decision-center.html">Decision centre</a></p>${d.simulation?`<p>Simulated failed machines: ${esc(d.simulation.failed_machine_ids.join(', ')||'None in this snapshot')}<br>${esc(d.simulation.source)}</p>`:''}<p>Weather observation: ${esc(d.weather.current?.time||'No record')} · ${num(d.weather.current?.temperature_2m)} °C · precipitation ${num(d.weather.current?.precipitation)} mm in current interval. Daily rainfall forecast is used for daily/shift production.</p><p>Approved stockpile dispatch: ${num(d.stockpile_supply_mt||0)} MT (extra supply, not mined output).</p>${(d.approved_actions||[]).map(a=>`<div class="notice"><b>${esc(a.title)}</b><br>Planned recovery applied: ${num(a.gain_mt)} MT · Action cost: ${money(a.cost_inr)}<br>Expected effect only; actual output unchanged.<button data-action="${a.id}" data-state="rejected">Revoke plan</button><button data-action="${a.id}" data-state="completed">Record actual outcome</button></div>`).join('')}</section>`}
window.addEventListener('storage',e=>{if(e.key==='mineos-site'){state.selected=e.newValue||'';$('#site').value=state.selected;render()}else if(e.key==='mineos-scenario-'+state.selected&&['production','decision-center'].includes(page))render();else if(e.key==='mineos-action-update'&&['production','decision-center','maintenance','reports'].includes(page))render()});

async function evidenceForms(){
 if(!state.selected){$('#content').insertAdjacentHTML('beforeend','<p>Select a mine to enter source-backed records.</p>');return}
 const previous=await api('/site-inputs/'+state.selected);
 const field=(name,label,type='text',extra='')=>`<label>${label}<input name="${name}" type="${type}" ${extra}></label>`;
 const provenance=field('source','Source document / reference','text','required minlength="5"')+field('observed_at','Record date','date','required')+field('operator','Recorded by','text','required minlength="2"');
 const sections=[['site-evidence','Mine mapping and costs',`<label>Mine type<select name="mine_type"><option>Unknown</option><option>Underground</option><option>Opencast</option><option>Mixed</option></select></label><label>Documented depth m<input name="depth_m" type="number" min="0" max="5000"></label><label>Documented production block<select name="block"><option value="">Unknown / no mapping</option><option>Block-A</option><option>Block-B</option><option>Block-C</option></select></label>`+[['price_per_tonne','Price per tonne'],['variable_cost_per_tonne','Variable cost per tonne'],['stockpile_mt','Stockpile MT'],['processing_headroom_tph','Spare capacity t/h'],['stockpile_handling_per_tonne','Handling cost/tonne'],['transport_speed_kph','Transport km/h'],['mobilization_inr','Mobilisation cost'],['transport_inr_per_km','Transport cost/km'],['overtime_cost_per_hour','Overtime cost/hour']].map(([k,l])=>field(k,l,'number','min="0" step="any"')).join('')],['machine-evidence','Machine assignment and capacity',field('machine_id','Benchmark record ID (EQ-...)','text','required')+field('asset_reference','Real asset / register reference','text','required minlength="2"')+field('latitude','Recorded latitude','number','min="-90" max="90" step="any" required')+field('longitude','Recorded longitude','number','min="-180" max="180" step="any" required')+field('capacity_tph','Recorded capacity t/h','number','min="0" step="any" required')+'<label><input type="checkbox" name="standby">Standby according to record</label>'],['shift-evidence','Shift production and blasting log',field('day','Shift date','date','required')+'<label>Shift<select name="shift"><option>Shift-1</option><option>Shift-2</option><option>Shift-3</option></select></label>'+field('actual_mt','Recorded actual MT','number','min="0" step="any" required')+field('target_mt','Recorded target MT','number','min="0" step="any" required')+field('blast_delay_hours','Recorded blast delay hours','number','min="0" max="8" step="any" required')]];
 $('#content').insertAdjacentHTML('beforeend',`<section class="panel"><h2>Source-backed inputs · ${esc(selectedMine()?.name)}</h2><p>Entries are operator supplied, not independently verified. Machine mapping does not turn benchmark sensor readings into live telemetry. Blank cost fields remain labelled scenario assumptions.</p>${sections.map(([id,title,html])=>`<details><summary>${title}</summary><form id="${id}"><div class="form-grid">${html}${provenance}</div><button>Save record</button><p class="save-status" aria-live="polite"></p></form></details>`).join('')}<details><summary>Saved source records</summary><pre style="white-space:pre-wrap">${esc(JSON.stringify(previous,null,2))}</pre></details></section>`);
 for(const [k,v] of Object.entries(previous.inputs)){const el=$('#site-evidence').elements.namedItem(k);if(el)el.value=v;}
 for(const [id] of sections)$('#'+id).onsubmit=async e=>{e.preventDefault();const form=e.target,body={};for(const [k,v] of new FormData(form)){if(v!=='')body[k]=form.elements[k].type==='number'?Number(v):v;}let endpoint='/site-inputs/'+state.selected;if(id==='machine-evidence'){endpoint='/machine-inputs/'+encodeURIComponent(body.machine_id);delete body.machine_id;body.mine_id=state.selected;body.standby=form.elements.standby.checked;}if(id==='shift-evidence')endpoint='/shift-logs/'+state.selected;try{await api(endpoint,body);form.querySelector('.save-status').textContent='Saved with source and date. Reopen Production to apply.';localStorage.setItem('mineos-action-update',Date.now())}catch(err){form.querySelector('.save-status').textContent=err.message}};
}
